["Icon"] = "INTERFACE\\ICONS\\Ability_Spy",
["Enabled"] = true,
["Revision"] = 456,
["semver"] = "1.0.1",
["Author"] = "Zenshoes-Area 52",
["Desc"] = "Abbreviates names on nameplates",
["Prio"] = 99,
["version"] = 2,
["PlaterCore"] = 1,
["Options"] = {
},
["LastHookEdited"] = "Nameplate Updated",
["Name"] = "Abbreviated Names",
